import { MAP_BOX } from "../scene/CameraRig.jsx";
import { sectionName } from "../venues.js";
import damaiWuxi from "./damai/wuxiDamaiHotspots.json";
import damaiWuxiImg from "./damai/wuxi_damai_map.webp";

// Official Damai seat-map bitmaps with traced per-section (and per price band) hotspots.
// Generated by scripts/trace_damai_map.py — the picture IS the Damai map; closed
// (obstructed) sections have no hotspot and stay darkened exactly as Damai shows them.
const DAMAI = { wuxi: { ...damaiWuxi, image: damaiWuxiImg } };

function DamaiMap({ venue, map, selected, onSelect, leaving }) {
  const [, , vw, vh] = map.viewBox;
  return (
    <div className={`map-layer damai ${leaving ? "leaving" : ""}`}>
      <svg className="seat-svg" viewBox={`0 0 ${vw} ${vh}`} preserveAspectRatio="xMidYMid meet" role="group" aria-label={venue.meta.aria}>
        <defs>
          <filter id="damai-feather" x="-10%" y="-10%" width="120%" height="120%"><feGaussianBlur stdDeviation="5" /></filter>
          <mask id="damai-edge" maskUnits="userSpaceOnUse" x="0" y="0" width={vw} height={vh}>
            <rect x="6" y="12" width={vw - 12} height={vh - 18} fill="#fff" filter="url(#damai-feather)" />
          </mask>
        </defs>
        <image href={map.image} x="0" y="0" width={vw} height={vh} preserveAspectRatio="none" mask="url(#damai-edge)" />
        {venue.sections.map((s) => {
          const d = map.hotspots[s.id];
          if (!d || s.unsold) return null;
          const on = selected?.id === s.id;
          return (
            <g key={s.id} data-id={s.id} className={`sec hot ${on ? "on" : ""}`} role="button" tabIndex={0} aria-label={`${sectionName(s)} · ¥${s.price}`} onClick={() => onSelect(s)} onKeyDown={(e) => e.key === "Enter" && onSelect(s)}>
              <path d={d} />
            </g>
          );
        })}
      </svg>
    </div>
  );
}

const polyPoints = (s) => s.points.map((p) => p.join(",")).join(" ");

// Section picker — every non-closed numbered section is its own tap target.
export function SeatMap({ venue, selected, onSelect, leaving }) {
  const damai = DAMAI[venue.id];
  if (damai) return <DamaiMap venue={venue} map={damai} selected={selected} onSelect={onSelect} leaving={leaving} />;
  const { w, h } = MAP_BOX;
  const { sections, stage, meta } = venue;
  return (
    <div className={`map-layer ${leaving ? "leaving" : ""}`}>
      <svg className="seat-svg" viewBox={`${-w / 2} ${-h / 2} ${w} ${h}`} preserveAspectRatio="xMidYMid meet" role="group" aria-label={meta.aria}>
        <rect x={-stage.halfX} y={-stage.halfZ} width={stage.halfX * 2} height={stage.halfZ * 2} className="stage-rect" />
        <text x="0" y="3.4" className="stage-label">舞 台</text>
        {sections.map((s) => {
          const on = selected?.id === s.id, floor = s.kind === "floor", label = s.mapLabel === undefined ? s.id : s.mapLabel;
          if (s.unsold)
            return (
              <g key={s.id} className="sec unsold" aria-hidden="true">
                <polygon points={polyPoints(s)} fill={s.color} />
                {label && <text x={s.label.x} y={s.label.z + 0.9} fontSize={2.5} opacity={0.45}>{label}</text>}
              </g>
            );
          return (
            <g key={s.id} data-id={s.id} className={`sec ${on ? "on" : ""}`} role="button" tabIndex={0} aria-label={sectionName(s)} onClick={() => onSelect(s)} onKeyDown={(e) => e.key === "Enter" && onSelect(s)}>
              <polygon points={polyPoints(s)} fill={on ? "#6fffd2" : s.color} />
              {label && <text x={s.label.x} y={s.label.z + (floor ? 1 : 0.9)} fontSize={floor ? 2.9 : 2.5}>{label}</text>}
            </g>
          );
        })}
      </svg>
    </div>
  );
}
